import {experienceLedger,growth} from './expedition-growth.mjs';
import {ADVANCEMENTS} from './expedition-advancement-data.mjs';
import {equipmentName} from './expedition-equipment.mjs';
import {HEROES,GEAR} from './expedition-data.mjs';
import {recruitmentStatus} from './expedition-roster.mjs';
const growthSummary=m=>{const l=experienceLedger(m);return `<p class=roster-growth data-roster-growth="${m.id}">成长阶段${growth(m).level} · 累计${l.earned}经验<br>可用${l.available} · 训练投入${l.training}经验<br>后期进阶：${m.advancement?ADVANCEMENTS[m.advancement.path].name:'未选择'}</p>`;};
export function rosterHome(g){
 const active=g.lineup.map(id=>HEROES.find(h=>h.id===id)),bench=g.members.filter(m=>!g.lineup.includes(m.id));
 return `<section class="guild-panel roster-home" data-guild-pane="roster"><p class="eyebrow">海岸公会 / 招募名册</p><h2>为这次远征，选择同行的人。</h2><p>一位主角＋五名伙伴出战。候补保留装备、经验与个人战术；当前只有出战者获得远征经验。同职业成员分别持有资产，补给仍由全队共享。</p><div class="roster-active">${active.map(h=>`<article><span class="portrait ${h.portrait}" aria-hidden="true"></span><b>${h.name}</b><small>${h.role} · ${g.command?.heroId===h.id?'我的英雄':'出战伙伴'}</small>${growthSummary(g.members.find(m=>m.id===h.id))}</article>`).join('')}</div>${!g.command?'<p>请到“我的英雄与伙伴”先选定主角，再替换伙伴。</p>':''}<h3>候补伙伴 · ${bench.length}</h3><div class="companion-grid">${bench.map(m=>{const h=HEROES.find(h=>h.id===m.id);return `<article><h3>${h.name} · ${h.role}</h3><p>${equipmentName(m.gear)}</p>${growthSummary(m)}<label>替换 <select id="replace-${h.id}" aria-label="${h.name}替换谁">${active.filter(h=>h.id!==g.command?.heroId).map(h=>`<option value="${h.id}">${h.name} · ${h.role}</option>`).join('')}</select></label><button data-swap="${h.id}" ${g.pending||!g.command?'disabled':''}>编入${h.name}</button><button data-ready-member="${h.id}">装备与成长</button></article>`;}).join('')||'<p>当前没有候补，可在下方招募。</p>'}</div><h3>来到营地的旅人</h3><div class="companion-grid">${HEROES.filter(h=>h.recruit).map(h=>{const s=recruitmentStatus(g,h.id),owned=g.members.some(m=>m.id===h.id);return `<article><h3>${h.name} · ${h.role}</h3><p>${h.story}</p><p>完成 ${s.completed} 次远征后可招募 · ${s.cost} 公会金币</p><button data-recruit="${h.id}" ${s.available?'':'disabled'}>${owned?'已加入名册':'招募'+h.name}</button></article>`;}).join('')}</div><p>招募不会自动换人；编入后请到出征准备核对站位、协作覆盖与资源。当前候补使用职业示意头像。</p><button data-guild-tab="departure" class="primary">核对出战队伍 →</button></section>`;
}
